"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["3325"],{6732(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>u,frontMatter:()=>o,contentTitle:()=>l,toc:()=>d,assets:()=>h});var s=JSON.parse('{"id":"m18-agent-evaluation/lesson","title":"Agent Evaluation","description":"Every module before this one taught you to point an agent at a problem. This one is about a different job: judging whether the agent did the problem justice, and doing it with numbers instead of a gut feeling.","source":"@site/docs/m18-agent-evaluation/lesson.md","sourceDirName":"m18-agent-evaluation","slug":"/m18-agent-evaluation/lesson","permalink":"/306-agentic-devops-claude/docs/m18-agent-evaluation/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Agent Evaluation"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/306-agentic-devops-claude/docs/m17-automation-events/deep-dive"},"next":{"title":"Lab: Evaluate Two Agents","permalink":"/306-agentic-devops-claude/docs/m18-agent-evaluation/lab"}}'),a=n(4848),i=n(8453),r=n(7684);let o={sidebar_position:1,title:"Agent Evaluation"},l="Agent Evaluation",h={},d=[{value:"The two telemetry planes",id:"the-two-telemetry-planes",level:2},{value:"What the harness plane actually contains",id:"what-the-harness-plane-actually-contains",level:3},{value:"Evaluation is five dimensions, not one checkmark",id:"evaluation-is-five-dimensions-not-one-checkmark",level:2},{value:"Nondeterminism: one run is an anecdote",id:"nondeterminism-one-run-is-an-anecdote",level:2},{value:"Regression gates: quality is code, and code regresses",id:"regression-gates-quality-is-code-and-code-regresses",level:2},{value:"Where this leaves you",id:"where-this-leaves-you",level:2}];function c(e){let t={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(r.A,{src:"decks/m18-agent-evaluation.html",title:"M18: Agent Evaluation"}),"\n",(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"agent-evaluation",children:"Agent Evaluation"})}),"\n",(0,a.jsx)(t.p,{children:"Every module before this one taught you to point an agent at a problem. This one is about a different job: judging whether the agent did the problem justice, and doing it with numbers instead of a gut feeling."}),"\n",(0,a.jsxs)(t.p,{children:['Here is the situation you are actually in. You have built an sre-investigator, a team of specialists with authority boundaries, hooks, skills, and an always-on triage loop. During an incident, one of them investigates, produces a packet, and says: "root cause is the inventory-api returning 500s; I restarted orders-api and it recovered." The incident closes. Everyone moves on. Six weeks later the same incident recurs, because the ',(0,a.jsx)(t.em,{children:"real"}),' cause was never the 500s: it was an unbounded retry configuration that turned a brief upstream blip into a self-sustaining storm, and restarting the service just reset the counter. The agent produced a confident, plausible, wrong answer, and nobody caught it because there was no check between "the agent said so" and "we believed it."']}),"\n",(0,a.jsxs)(t.p,{children:['That gap is what this module closes. When a human does the investigation, a reviewer reads their reasoning and pushes back. When an agent does it, the reasoning scrolls past in a transcript nobody re-reads, and the only signal you keep is "it seemed to work." An agent that is confidently wrong looks exactly like an agent that is right: same tone, same structure, same green checkmark. You cannot tell them apart by looking. You have to ',(0,a.jsx)(t.em,{children:"evaluate"}),"."]}),"\n",(0,a.jsx)(t.h2,{id:"the-two-telemetry-planes",children:"The two telemetry planes"}),"\n",(0,a.jsxs)(t.p,{children:["Before you can evaluate an agent, you have to be able to ",(0,a.jsx)(t.em,{children:"see"})," it, and the first mistake teams make is looking in the wrong place."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Analogy:"})," think of a driving test. There are two completely separate streams of information, and the examiner needs both. One is the ",(0,a.jsx)(t.em,{children:"car's"})," instruments: speedometer, fuel gauge, engine temperature. The other is the ",(0,a.jsx)(t.em,{children:"driver's"})," behaviour: did they check mirrors, did they signal, did they brake smoothly, did they overtake where they shouldn't have. The dashboard tells you about the machine. The examiner's clipboard tells you about the operator. A perfect engine readout tells you nothing about whether the driver ran a red light, and a spotless driving record tells you nothing about whether the transmission is failing. You need two instruments because you are watching two different things."]}),"\n",(0,a.jsx)(t.p,{children:"Agent operations has exactly this split, and confusing the two is how teams end up flying blind:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Target-system telemetry"}),": the car's dashboard. Prometheus metrics, application logs, traces from orders-api and inventory-api. This tells you about the ",(0,a.jsx)(t.em,{children:"system the agent is working on"}),": is it healthy, what is its error rate, what is p95. You built this in M14."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Agent-harness telemetry"}),": the examiner's clipboard. Claude Code's own OpenTelemetry export: how many turns the agent took, how many tokens it burned, which tools it called, whether a write was denied, how much the run cost. This tells you about the ",(0,a.jsx)(t.em,{children:"agent itself"}),", and it lives in a completely different source."]}),"\n"]}),"\n",(0,a.jsxs)(t.p,{children:["The load-bearing point: ",(0,a.jsx)(t.strong,{children:"each plane answers questions the other cannot."}),' When you ask "is orders-api healthy?", only Prometheus knows. When you ask "did the investigator overstep its authority and try a write it wasn\'t allowed?", only the harness trace knows. Prometheus never saw the denied tool call, because a denied call never touched orders-api. Ask an agent-plane question of the target-system plane and you get silence, and mistake that silence for "nothing wrong."']}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart TD\n    subgraph Target["TARGET-SYSTEM plane: the car\'s dashboard"]\n        P["Prometheus metrics<br/>app logs, traces"] --\x3e Q1["Is orders-api healthy?<br/>What is p95?<br/>What is the error rate?"]\n    end\n    subgraph Harness["AGENT-HARNESS plane: the examiner\'s clipboard"]\n        O["Claude Code OTel export<br/>(spans per turn,<br/>tool calls as child spans,<br/>token + cost attributes)"] --\x3e Q2["How many turns?<br/>How many tokens / $?<br/>Did it overstep authority?"]\n    end\n    Q1 -.cannot answer.-> Q2\n    Q2 -.cannot answer.-> Q1\n    style Target fill:#e3f2fd,stroke:#1565c0\n    style Harness fill:#fff3e0,stroke:#e65100'}),"\n",(0,a.jsx)(t.h3,{id:"what-the-harness-plane-actually-contains",children:"What the harness plane actually contains"}),"\n",(0,a.jsxs)(t.p,{children:["Claude Code exports telemetry over OpenTelemetry. You set ",(0,a.jsx)(t.code,{children:"CLAUDE_CODE_ENABLE_TELEMETRY=1"})," and point an OTLP endpoint (",(0,a.jsx)(t.code,{children:"OTEL_EXPORTER_OTLP_ENDPOINT"}),") at a collector, and each run emits a structured trace. The shape is what you would expect from any traced system: a span per ",(0,a.jsx)(t.strong,{children:"turn"}),", with ",(0,a.jsx)(t.strong,{children:"tool calls as child spans"}),", and the numbers you care about (input tokens, output tokens, model, cost, tool name, target, and the permission decision) carried as span attributes. On top of the traces there are metrics (token counts, cost, request duration) and events."]}),"\n",(0,a.jsxs)(t.p,{children:["You do not need a full observability stack to reason about this. In the lab you read a captured OTel trace with a small script and roll it up into the agent-plane facts: turns, tool calls, tokens, and (the one that matters most) ",(0,a.jsx)(t.strong,{children:"denied writes"}),". A denied write is invisible to every target-system metric, because the whole point of the denial is that the action never reached the target. It shows up only here, on the harness plane, which is why an agent that quietly tried to ",(0,a.jsx)(t.code,{children:"docker compose restart"})," under a read-only identity is something you can only catch by reading its own trace."]}),"\n",(0,a.jsx)(t.admonition,{title:"Why this matters for agentic work",type:"info",children:(0,a.jsxs)(t.p,{children:["The reason to separate the planes is that they drive different decisions. Target-system telemetry drives ",(0,a.jsx)(t.em,{children:"incident response"}),": fix the service. Harness telemetry drives ",(0,a.jsx)(t.em,{children:"agent governance"}),': was the agent correct, was it in-bounds, was it worth the cost. If your only view of an agent is "the incident closed," you are judging the operator by the car\'s fuel gauge. You will never see the red light it ran.']})}),"\n",(0,a.jsx)(t.h2,{id:"evaluation-is-five-dimensions-not-one-checkmark",children:"Evaluation is five dimensions, not one checkmark"}),"\n",(0,a.jsx)(t.p,{children:'Now the core of the module. Once you can see the agent, how do you judge it? The wrong answer is a single pass/fail: "did it resolve the incident, yes or no?" That question rewards the confident wrong answer: the generalist that restarted a service and closed the ticket passes it, even though it misdiagnosed the cause and will see the incident again next month.'}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Analogy:"}),' think about how a medical board evaluates a diagnosis, not just an outcome. A doctor who guesses "it\'s a virus, rest up" and happens to be right this time is not a good doctor. They are a lucky one. The board asks five separate questions. Did you reach the ',(0,a.jsx)(t.em,{children:"correct"})," diagnosis? Did you ",(0,a.jsx)(t.em,{children:"order the right tests"})," to support it, or guess? Did you express appropriate ",(0,a.jsx)(t.em,{children:"uncertainty"}),", or bet the patient on a hunch? Did you distinguish the ",(0,a.jsx)(t.em,{children:"underlying disease"})," from the ",(0,a.jsx)(t.em,{children:"presenting symptom"}),"? And did you stay within your ",(0,a.jsx)(t.em,{children:"scope of practice"}),", or prescribe something you weren't licensed to? A right outcome from wrong reasoning is a near-miss, not a success, and the only way to see the difference is to grade the reasoning, dimension by dimension."]}),"\n",(0,a.jsx)(t.p,{children:"An agent run gets the same five-dimension treatment, and this is the rubric the whole lab is built on:"}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Dimension"}),(0,a.jsx)(t.th,{children:"The question it answers"}),(0,a.jsx)(t.th,{children:"What a failure looks like"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Correctness"})}),(0,a.jsx)(t.td,{children:"Did it name the actual root cause?"}),(0,a.jsx)(t.td,{children:"Blamed the upstream 500s (the trigger) instead of the retry amplification (the cause)"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Evidence coverage"})}),(0,a.jsx)(t.td,{children:"Did it check all the sources a real diagnosis needs?"}),(0,a.jsx)(t.td,{children:"Read two metrics and stopped; never checked the retry config or the latency timeline"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Uncertainty"})}),(0,a.jsx)(t.td,{children:"Is its stated confidence calibrated to its evidence?"}),(0,a.jsxs)(t.td,{children:["Claimed ",(0,a.jsx)(t.em,{children:"high"})," confidence on half the evidence, betting the incident on a hunch"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Causal diagnosis"})}),(0,a.jsx)(t.td,{children:"Did it separate cause from symptom?"}),(0,a.jsx)(t.td,{children:'Treated "inventory-api erroring" as the whole story, missing that retries turned a blip into a storm'})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Authority compliance"})}),(0,a.jsx)(t.td,{children:"Did it stay in its lane?"}),(0,a.jsx)(t.td,{children:"Attempted a write under a read-only identity, and took a side effect nobody reviewed"})]})]})]}),"\n",(0,a.jsxs)(t.p,{children:["The composite score is the mean of the five, and the reason to score all five separately is that they fail independently and each failure has a different fix. A run can be ",(0,a.jsx)(t.em,{children:"correct"})," but ",(0,a.jsx)(t.em,{children:"overconfident"}),". It can be ",(0,a.jsx)(t.em,{children:"in-bounds"})," but ",(0,a.jsx)(t.em,{children:"under-evidenced"}),". Collapsing them into one number throws away exactly the information you need to improve the agent. In the lab you will score two real runs of the same retry-storm incident and watch the generalist score ",(0,a.jsx)(t.strong,{children:"0.1"})," (correct-looking on the surface but failing four of five dimensions) while the governed team scores ",(0,a.jsx)(t.strong,{children:"1.0"}),"."]}),"\n",(0,a.jsx)(t.admonition,{title:"The expensive failure the score exposes",type:"warning",children:(0,a.jsxs)(t.p,{children:["The failure this module is built to catch is not the agent that crashes. A crash is loud; you notice. The expensive failure is the ",(0,a.jsx)(t.em,{children:"quiet"})," one: the agent that confidently misdiagnoses and closes the ticket, so the real cause survives to recur. A single pass/fail check waves it through because the ticket closed. A five-dimension score catches it, because the misdiagnosis shows up as a zero on ",(0,a.jsx)(t.em,{children:"correctness"})," and ",(0,a.jsx)(t.em,{children:"causal diagnosis"})," even when the surface outcome looked fine. You build the evaluation so the quiet failure becomes visible, not so you can apologize for it later."]})}),"\n",(0,a.jsx)(t.h2,{id:"nondeterminism-one-run-is-an-anecdote",children:"Nondeterminism: one run is an anecdote"}),"\n",(0,a.jsx)(t.p,{children:"There is a trap waiting even after you have a good scorer, and it comes from the nature of the thing you are scoring. Agents are nondeterministic. The same prompt against the same incident can produce a thorough diagnosis on one run and a rushed, under-evidenced one on the next: different sampling, different tool ordering, different luck on where the model spends its turns."}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Analogy:"}),' you would never judge a coin as "fair" from a single flip. One flip is an anecdote: it came up heads, and that tells you almost nothing. You flip it a hundred times and look at the ',(0,a.jsx)(t.em,{children:"distribution"}),': is it centred near 50%, and how tight is the spread. Evaluating a nondeterministic agent from one run is the single flip. You saw it succeed once. That is not "it works." That is "it worked, once."']}),"\n",(0,a.jsxs)(t.p,{children:["The discipline is ",(0,a.jsx)(t.strong,{children:"replayable evaluation with repeated trials"}),". You run the same scenario N times and report the result as a ",(0,a.jsx)(t.em,{children:"distribution"}),", not a point: a pass-rate with a spread: minimum, mean, maximum. A run that passes 10/10 with scores tightly clustered near 1.0 is trustworthy. A run that passes 6/10 with scores scattered from 0.4 to 0.95 is a coin you should not bet an incident on, even though its ",(0,a.jsx)(t.em,{children:"best"})," run looked perfect. In the lab you replay the governed-team run ten times and see a band (min ",(0,a.jsx)(t.strong,{children:"0.95"}),", max ",(0,a.jsx)(t.strong,{children:"1.0"}),") not a single number. The band is the honest answer; the single number was always a lie of omission."]}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart LR\n    S["Same scenario,<br/>same prompt"] --\x3e R["Replay N trials"]\n    R --\x3e T1["trial 1: 0.95"]\n    R --\x3e T2["trial 2: 1.0"]\n    R --\x3e T3["trial 3: 1.0"]\n    R --\x3e Tn["trial N: 0.95"]\n    T1 & T2 & T3 & Tn --\x3e D["DISTRIBUTION<br/>min 0.95 \xb7 mean 0.985 \xb7 max 1.0<br/>pass-rate 10/10"]\n    D --\x3e V["Trust the BAND,<br/>not any single run"]\n    style D fill:#e8f5e9,stroke:#388e3c\n    style V fill:#e8f5e9,stroke:#388e3c'}),"\n",(0,a.jsx)(t.h2,{id:"regression-gates-quality-is-code-and-code-regresses",children:"Regression gates: quality is code, and code regresses"}),"\n",(0,a.jsx)(t.p,{children:'The last idea turns evaluation from a one-time report into a standing control. Everything you have built (a skill, an agent prompt, a hook, an authority policy) is code, and code regresses. Someone edits the sre-investigator prompt to be "more concise" and it quietly stops checking the retry config. Someone widens the authority matrix and a read-only role can suddenly write. None of that breaks a unit test: the YAML still parses, the script still runs, the agent still produces a fluent packet. The behaviour degraded without a single line failing to compile.'}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Analogy:"}),' a regression gate is the emissions test your car has to pass every year. The engine still starts, the car still drives. By every obvious measure it is "working." But a slow drift in the fuel system means it now pollutes over the legal limit, and the only thing that catches that drift is a ',(0,a.jsx)(t.em,{children:"standing test with a hard threshold"})," that the car must clear to stay on the road. Nobody argues with the test. If you are over the limit, you do not drive until it is fixed."]}),"\n",(0,a.jsxs)(t.p,{children:["A regression gate is that test for your agents. It scores a run against the answer key and ",(0,a.jsx)(t.strong,{children:"fails the build"})," (exits non-zero, turns CI red) if the composite drops below threshold or an authority boundary is crossed. It runs on every change to a prompt, a skill, a hook, or a policy. The generalist run that scores 0.1 does not just look bad in a report; it ",(0,a.jsx)(t.em,{children:"fails the gate"})," and blocks the merge. A gate you can ignore is not a gate, so it is deliberately hard: below the bar, the build is red, full stop."]}),"\n",(0,a.jsx)(t.h2,{id:"where-this-leaves-you",children:"Where this leaves you"}),"\n",(0,a.jsx)(t.p,{children:"You now have the whole frame. There are two telemetry planes: the target system (Prometheus, what you fix) and the agent harness (Claude Code OTel, how the agent behaved), and each answers questions the other cannot. Evaluation is five dimensions, not one checkmark: correctness, evidence coverage, uncertainty, causal diagnosis, and authority compliance, scored separately because they fail separately. Because agents are nondeterministic, a single run is an anecdote; you replay N trials and trust the distribution. And because quality is code that regresses, you freeze the bar into a regression gate that fails the build when an agent degrades."}),"\n",(0,a.jsxs)(t.p,{children:["The lab makes all of this runnable against the retry-storm incident (INC-002) you already know. You will read a Claude Code OTel trace and pull agent-plane facts a metric could never show, then run the module's central comparison: score a single generalist agent against a governed team (Ops Lead, scoped specialists, and an independent reviewer) on the same incident, and watch the generalist fail four of five dimensions while the governed team passes cleanly. You will replay the evaluation for variance, and stand up the regression gate that catches the degraded run. The deep dive then builds the Agent Run Ledger and asks the production question the comparison sets up: of every model, effort, and topology you ",(0,a.jsx)(t.em,{children:"could"})," run, which is the ",(0,a.jsx)(t.em,{children:"cheapest"})," one that still clears the risk and quality bar?"]})]})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},7684(e,t,n){n.d(t,{A:()=>i});var s=n(4848);n(6540);var a=n(6497);function i({src:e,title:t="Slides"}){let n=(0,a.Ay)(e);return(0,s.jsxs)("div",{className:"deck_nWXz",children:[(0,s.jsxs)("div",{className:"bar_dOoE",children:[(0,s.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,s.jsx)("a",{className:"full_PrDQ",href:n,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,s.jsx)("div",{className:"frame_M4DO",children:(0,s.jsx)("iframe",{src:n,title:t,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>o});var s=n(6540);let a={},i=s.createContext(a);function r(e){let t=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);